const rows = $input.all().map(function (i) { return i.json; });
const f = $('Subscription Audit Form').first().json;
const groups = {};
for (const r of rows) {
  const raw = r.Amount || r.amount || r.Debit || r.debit || 0;
  const amt = Math.abs(Number(String(raw).replace(/[^0-9.-]/g, '')) || 0);
  if (!amt) continue;
  const desc = String(r.Description || r.description || r.Memo || r.Details || '');
  if (!desc) continue;
  const key = desc.toLowerCase().replace(/[0-9]/g, '').replace(/[^a-z ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 24);
  if (!key) continue;
  const date = String(r.Date || r.date || r['Transaction Date'] || '');
  if (!groups[key]) { groups[key] = { merchant: key, charges: [], dates: [] }; }
  groups[key].charges.push(amt);
  groups[key].dates.push(date);
}
const recurring = [];
for (const k of Object.keys(groups)) {
  const g = groups[k];
  if (g.charges.length < 2) continue;
  const avg = g.charges.reduce(function (a, b) { return a + b; }, 0) / g.charges.length;
  const spread = Math.max.apply(null, g.charges) - Math.min.apply(null, g.charges);
  const stable = avg > 0 && spread / avg < 0.25;
  if (!stable) continue;
  recurring.push({ merchant: g.merchant, times: g.charges.length, averageAmount: Math.round(avg * 100) / 100, totalPaid: Math.round(g.charges.reduce(function (a, b) { return a + b; }, 0)), lastSeen: g.dates.sort().slice(-1)[0] || '' });
}
recurring.sort(function (a, b) { return b.totalPaid - a.totalPaid; });
const top = recurring.slice(0, 25);
return [{ json: {
  email: f['Your email'] || '',
  transactionCount: rows.length,
  recurringCount: top.length,
  totalRecurringSpend: top.reduce(function (a, b) { return a + b.totalPaid; }, 0),
  candidateText: top.map(function (t) { return t.merchant + ' | charged ' + t.times + ' times | avg ' + t.averageAmount + ' | total ' + t.totalPaid + ' | last ' + t.lastSeen; }).join('\n')
} }];

