=You are a personal finance analyst. The list below contains repeating charges detected in a bank statement. For each one work out what the service actually is from the merchant string, its category, the monthly and annual cost, and whether the person should keep, review or cancel it. Use "cancel" for obviously duplicated services or things charged repeatedly but rarely used, "review" when it depends on the person's habits, and "keep" for essentials such as utilities, insurance, rent or phone. Ignore anything that is clearly not a subscription, such as groceries or fuel. Also give the total annual cost and the realistic savings if the cancel and review items were dropped.

Repeating charges:
{{ $json.candidateText }}

parameters.jsCode:
const src = $json.output || $json;
const d = $('Detect Recurring Charges').item.json;
const list = Array.isArray(src.subscriptions) ? src.subscriptions : [];
const subs = list.map(function (s) { return { merchant: s.merchant || '', service: s.service || s.merchant || '', category: s.category || 'Other', monthlyCost: Number(s.monthly_cost) || 0, annualCost: Number(s.annual_cost) || 0, recommendation: String(s.recommendation || 'review').toLowerCase(), reason: s.reason || '' }; });
const cancels = subs.filter(function (s) { return s.recommendation === 'cancel' || s.recommendation === 'review'; });
return {
  email: d.email,
  subscriptionCount: subs.length,
  totalAnnualCost: Number(src.total_annual_cost) || 0,
  potentialSavings: Number(src.potential_savings) || 0,
  summary: src.summary || '',
  subscriptions: subs,
  cancelText: cancels.map(function (s) { return '- ' + s.service + ' (' + s.category + '): ' + s.annualCost + ' per year -> ' + s.recommendation + '. ' + s.reason; }).join('\n'),
  keepText: subs.filter(function (s) { return s.recommendation === 'keep'; }).map(function (s) { return '- ' + s.service + ': ' + s.annualCost + ' per year'; }).join('\n')
};
